{
  "command": "S=/tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad; sed -n 786,895p $S/txt/henderson2025_ns.txt | grep -v \"^$\" | head -80",
  "description": "Read Henderson 2025 compression ratio definition"
}

{
  "query": "Le Chat Issautier Meyer-Vernet 2012 \"The solar wind energy flux\" Solar Physics arXiv 70 W m-2 solar radius",
  "mode": "standard"
}

{
  "query": "Wang 2010 ApJ Letters \"On the relative constancy of the solar wind mass flux at 1 AU\" momentum flux speed",
  "mode": "standard"
}

{
  "query": "McGregor Hughes Arge Owens Odstrcil 2011 JGR \"The distribution of solar wind speeds during solar minimum: Calibration for numerical solar wind modeling constraints on the source\" density boundary",
  "mode": "standard"
}

{
  "url": "https://arxiv.org/pdf/1203.1316",
  "prompt": "Extract: the definition of the energy flux W (formula, including kinetic + gravitational terms), its normalization to 1 solar radius, the average value (W m^-2) with uncertainty and data sets used (Helios, Ulysses, Wind, years), dependence on speed and latitude (percent), solar cycle variation, and the corresponding value at 1 AU if given. Also any statements about n v^2 (momentum flux) or n v (mass flux) vs speed. Quote verbatim with section/figure/table numbers."
}

{
  "url": "https://arxiv.org/pdf/2405.09693",
  "prompt": "Extract how EUHFORIA sets plasma density, temperature and magnetic field at the 0.1 AU (21.5 Rsun) inner boundary from the WSA speed: exact formulas (e.g., n = n_fsw (v_fsw/v)^2, T = T_fsw n_fsw/n, B_r scaling), the constants used (v_fsw, n_fsw, T_fsw, B_fsw, any speed offset/subtraction e.g. 50 km/s), and cited references (Pomoell & Poedts 2018, Odstrcil, McGregor 2011). Quote verbatim with equation and section numbers."
}

{
  "command": "S=/tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad; T=/home/scabot/.claude/projects/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/tool-results; cp $T/webfetch-1792192564036-pwcwic.pdf $S/pdfs/lechat2012.pdf; cp $T/webfetch-1792192566856-ta0525.pdf $S/pdfs/euhforia_wsa2024.pdf; cd $S && for n in lechat2012 euhforia_wsa2024; do python3 -I scripts/ex.py pdfs/$n.pdf txt/$n.txt; wc -c txt/$n.txt; done; grep -n -a -E \"W m|W/m|±|Wm|79|70 \" txt/lechat2012.txt | head -60",
  "description": "Extract Le Chat 2012 and EUHFORIA WSA texts, search energy flux"
}

{
  "command": "S=/tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad; sed -n 1,30p $S/txt/lechat2012.txt; sed -n 55,72p $S/txt/lechat2012.txt; sed -n 195,260p $S/txt/lechat2012.txt; sed -n 410,600p $S/txt/lechat2012.txt",
