{
  "query": "WSA-ENLIL inner boundary density temperature \"momentum flux\" \"thermal pressure\" constant 21.5 Rs fast wind density 125 cm-3 temperature 0.8 MK",
  "mode": "standard"
}

{
  "query": "McGregor 2011 \"The radial evolution of solar wind speeds\" JGR Helios Ulysses acceleration slow wind beyond 0.3 AU",
  "mode": "standard"
}

{
  "query": "Ebert McComas Elliott Forsyth Gosling 2009 JGR \"Bulk properties of the slow and fast solar wind and interplanetary coronal mass ejections measured by Ulysses\" three polar orbits",
  "mode": "standard"
}

{
  "url": "https://arxiv.org/pdf/1810.04014",
  "prompt": "Extract fitted radial power-law exponents for density, speed, magnetic field, proton parallel/perpendicular/total temperature, alpha particles, in pure fast high-speed streams between 0.3 and 1 AU; the speed of the streams; table numbers."
}

{
  "url": "https://agupubs.onlinelibrary.wiley.com/doi/full/10.1029/2008JA013631",
  "prompt": "Extract Table values: mean/median solar wind speed, proton density (scaled to 1 AU), proton temperature, magnetic field magnitude, dynamic pressure for slow wind, fast wind and ICMEs; fitted radial power-law exponents for density, temperature, B (e.g., T ∝ R^-?), and table numbers. Quote verbatim."
}

{
  "url": "https://arxiv.org/pdf/2505.22386",
  "prompt": "Extract the exact formulas used to set density and temperature at the ENLIL inner boundary from WSA speed (momentum flux balance, thermal pressure balance), the reference fast-wind values (speed, density, temperature, B), and cited sources. Quote verbatim with equation/section numbers."
}

